// Lade YouTube-Kanäle und Streamer aus Config
const sources = JSON.parse($env.CLIPFARM_SOURCES || '{}');
const channels = sources.youtube_channels || [];

const results = [];

for (const channel of channels) {
  results.push({
    json: {
      type: 'youtube_channel',
      channel_id: channel,
      rss_url: `https://www.youtube.com/feeds/videos.xml?channel_id=${channel}`
    }
  });
}

return results;

// Parse RSS und filtere Videos der letzten 6 Stunden
const xml = $input.first().json.data;
const parser = new (require('fast-xml-parser').XMLParser)();
const feed = parser.parse(xml);

const entries = feed.feed?.entry || [];
const cutoff = new Date(Date.now() - 6 * 60 * 60 * 1000);
const results = [];

for (const entry of Array.isArray(entries) ? entries : [entries]) {
  const published = new Date(entry.published);
  if (published > cutoff) {
    const videoId = entry['yt:videoId'];
    results.push({
      json: {
        id: videoId,
        title: entry.title,
        url: `https://youtube.com/watch?v=${videoId}`,
        published: entry.published,
        channel_id: $input.first().json.channel_id,
        source_type: 'youtube'
      }
    });
  }
}

return results;

// Prüfe ob Video bereits verarbeitet wurde
const videoId = $input.first().json.id;

return [{
  json: {
    video_id: videoId,
    should_download: true
  }
}];
